import torch as t

def solve(w,b):
    class Affine(t.nn.Module):
        def __init__(self):
            super().__init__()
            self.weight=t.nn.Parameter(w.clone())
            self.bias=t.nn.Parameter(b.clone()) if b is not None else None
        def forward(self,x):
            y=x*self.weight
            return y if self.bias is None else y+self.bias
    return Affine()

